using System.Buffers;

// Allocates 1 MB on the LOH for every call: costly if done per request
static byte[] ReadNaive(Stream s) { var buf = new byte[1024 * 1024]; s.ReadExactly(buf); return buf; }

// Reuses pooled buffers instead
static int Checksum(Stream s)
{
    byte[] buffer = ArrayPool<byte>.Shared.Rent(1024 * 1024);
    try
    {
        int read = s.Read(buffer, 0, buffer.Length);
        int sum = 0;
        for (int i = 0; i < read; i++) sum += buffer[i];
        return sum;
    }
    finally
    {
        ArrayPool<byte>.Shared.Return(buffer);   // always return what you rent
    }
}

