public class ReportWriter : IDisposable
{
    private readonly StreamWriter _writer;   // managed resource we own
    private bool _disposed;

    public ReportWriter(string path) => _writer = new StreamWriter(path);

    public void Write(string line)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        _writer.WriteLine(line);
    }

    public void Dispose()
    {
        Dispose(disposing: true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (_disposed) return;
        if (disposing)
        {
            _writer.Dispose();               // only when called from Dispose()
        }
        // free unmanaged resources here (none in this class, so no finalizer)
        _disposed = true;
    }
}

public sealed class NativeBuffer : IDisposable
{
    private IntPtr _memory = System.Runtime.InteropServices.Marshal.AllocHGlobal(1024);

    public void Dispose()
    {
        Free();
        GC.SuppressFinalize(this);       // finalizer no longer needed
    }

    ~NativeBuffer() => Free();           // safety net if Dispose is forgotten

    private void Free()
    {
        if (_memory != IntPtr.Zero)
        {
            System.Runtime.InteropServices.Marshal.FreeHGlobal(_memory);
            _memory = IntPtr.Zero;
        }
    }
}

public sealed class AuditSink : IAsyncDisposable, IDisposable
{
    private readonly FileStream _stream = new("audit.log", FileMode.Append);
    private readonly StreamWriter _writer;

    public AuditSink() => _writer = new StreamWriter(_stream);

    public Task WriteAsync(string line) => _writer.WriteLineAsync(line);

    public async ValueTask DisposeAsync()
    {
        await _writer.DisposeAsync().ConfigureAwait(false);   // flushes asynchronously
        await _stream.DisposeAsync().ConfigureAwait(false);
    }

    public void Dispose()
    {
        _writer.Dispose();
        _stream.Dispose();
    }
}

