public class AsyncCache
{
    private readonly SemaphoreSlim _gate = new(1, 1);

    public async Task RefreshAsync(Func<Task> load)
    {
        await _gate.WaitAsync();
        try { await load(); }          // awaiting while holding the semaphore is fine
        finally { _gate.Release(); }
    }
}

public class Stats
{
    private int _requests;              // updated atomically
    private long _bytes;

    public void Record(int size)
    {
        Interlocked.Increment(ref _requests);           // atomic ++
        Interlocked.Add(ref _bytes, size);              // atomic += for long
    }

    public long Bytes => Interlocked.Read(ref _bytes);  // atomic 64-bit read

    private int _initialized;
    public bool TryInitOnce()
        => Interlocked.CompareExchange(ref _initialized, 1, 0) == 0;   // only the first caller wins
}

