public class PriceCache(HttpClient http)
{
    private readonly Dictionary<string, decimal> _cache = new();

    public ValueTask<decimal> GetPriceAsync(string sku)
    {
        if (_cache.TryGetValue(sku, out var price))
            return new ValueTask<decimal>(price);          // no allocation on a hit

        return new ValueTask<decimal>(LoadAsync(sku));     // miss: wrap a real Task
    }

    private async Task<decimal> LoadAsync(string sku)
    {
        string text = await http.GetStringAsync($"/prices/{sku}");
        return _cache[sku] = decimal.Parse(text);
    }
}

