using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

public interface IOrderRepository { Task<int> ArchiveOldOrdersAsync(CancellationToken ct); }

public sealed class ArchiveWorker(IServiceScopeFactory scopes, ILogger<ArchiveWorker> logger)
    : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var scope = scopes.CreateScope();                  // new scope per iteration
                var repo = scope.ServiceProvider.GetRequiredService<IOrderRepository>();
                int archived = await repo.ArchiveOldOrdersAsync(stoppingToken);
                logger.LogInformation("Archived {Count} orders", archived);
            }
            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
            {
                break;                                                   // normal shutdown
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Archive run failed; retrying later"); // don't kill the host
            }

            await Task.Delay(TimeSpan.FromMinutes(10), stoppingToken);
        }
    }
}
